window.MB_KNIGHTS=[{"id":"1-1","d6":1,"d12":1,"name":{"en":"The True Knight","pt":"O Cavaleiro Verdadeiro"},"en":{"property":["Polished mace (d8 hefty), mail (A1), plate (A1), and helm (A1)","Kite shield (d4, A1) marked with a symbol of the truth (see below)","Petulant steed (VIG 10, CLA 10, SPI 5, 5GD)"],"ability":{"name":"Punitive Stroke","text":"Make a melee Attack against a known liar. Get +d10 to the Attack, ignoring armour."},"passion":{"name":"Honesty","text":"Restore SPI when you tell the truth where a lie might be more beneficial."}},"pt":{"property":["Maça polida (d8 pesada), malha (A1), placas (A1) e elmo (A1)","Escudo gota (d4, A1) marcado com um símbolo da verdade (veja abaixo)","Corcel petulante (VIG 10, CLA 10, ESP 5, 5GD)"],"ability":{"name":"Golpe Punitivo","text":"Faça um Ataque corpo a corpo contra um mentiroso conhecido. Receba +d10 no Ataque, ignorando armadura."},"passion":{"name":"Honestidade","text":"Restaure ESP quando disser a verdade onde uma mentira seria mais vantajosa."}}},{"id":"1-2","d6":1,"d12":2,"name":{"en":"The Snare Knight","pt":"O Cavaleiro da Cilada"},"en":{"property":["Handaxe (d6) attached to wildrope (strong rope that blends perfectly into foliage), gambeson (A1)","Companion (see below) (VIG 5, CLA 10, SPI 7, 4GD, partially understands human speech)","Tattered steed (VIG 8, CLA 10, SPI 5, 2GD)"],"ability":{"name":"Wild Eye","text":"Observe a beast in secret. Learn a useful truth about their habitat."},"passion":{"name":"Empathy","text":"Restore SPI when you spare the life of a hostile animal."}},"pt":{"property":["Machadinha (d6) presa a corda-selvagem (corda forte que se mistura perfeitamente à folhagem), gambeson (A1)","Companheiro (veja abaixo) (VIG 5, CLA 10, ESP 7, 4GD, compreende parcialmente a fala humana)","Corcel maltrapilho (VIG 8, CLA 10, ESP 5, 2GD)"],"ability":{"name":"Olho Selvagem","text":"Observe uma fera em segredo. Aprenda uma verdade útil sobre o habitat dela."},"passion":{"name":"Empatia","text":"Restaure ESP quando poupar a vida de um animal hostil."}}},{"id":"1-3","d6":1,"d12":3,"name":{"en":"The Tourney Knight","pt":"O Cavaleiro do Torneio"},"en":{"property":["Greatlance (2d10 hefty when mounted, slow on foot) and 2 javelins (d6)","Gambeson (A1), arena plate (A1), fancy helm (A1, see below)","Horned stallion (VIG 12, CLA 10, SPI 5, 4GD, d6 trample)"],"ability":{"name":"Champion Vow","text":"Use immediately before a combat where there is a prize at stake. +d6 to melee attacks for the whole combat."},"passion":{"name":"Hatred","text":"Restore SPI when you refuse a plea for forgiveness."}},"pt":{"property":["Lança pesada (2d10 pesada quando montado, lenta a pé) e 2 azagaias (d6)","Gambeson (A1), placas de arena (A1), elmo adornado (A1, veja abaixo)","Garanhão chifrudo (VIG 12, CLA 10, ESP 5, 4GD, d6 atropelar)"],"ability":{"name":"Voto de Campeão","text":"Use imediatamente antes de um combate onde haja um prêmio em jogo. +d6 em ataques corpo a corpo durante todo o combate."},"passion":{"name":"Ódio","text":"Restaure ESP quando recusar um pedido de perdão."}}},{"id":"1-4","d6":1,"d12":4,"name":{"en":"The Bloody Knight","pt":"O Cavaleiro Sangrento"},"en":{"property":["Longaxe (d10 long), mail (A1), brutal plate (A1 only when Wounded), helm (A1)","Sacks of strong alcohol, to which you're largely resistant (see below, restock each new Season)","Bullish warhorse (VIG 15, CLA 5, SPI 5, 3GD, d6 trample)"],"ability":{"name":"Slaughter Echo","text":"Use immediately after defeating an opponent. Your next melee Attack in this combat gains Blast."},"passion":{"name":"Justice","text":"Restore SPI when you restore the balance of justice."}},"pt":{"property":["Machado longo (d10 longo), malha (A1), placas brutais (A1 apenas quando Ferido), elmo (A1)","Sacos de álcool forte, ao qual você é amplamente resistente (veja abaixo, reabastecem a cada nova Estação)","Cavalo de guerra taurino (VIG 15, CLA 5, ESP 5, 3GD, d6 atropelar)"],"ability":{"name":"Eco do Massacre","text":"Use imediatamente após derrotar um oponente. Seu próximo Ataque corpo a corpo neste combate ganha Explosão."},"passion":{"name":"Justiça","text":"Restaure ESP quando restaurar o equilíbrio da justiça."}}},{"id":"1-5","d6":1,"d12":5,"name":{"en":"The Moss Knight","pt":"O Cavaleiro do Musgo"},"en":{"property":["Branch cudgel (d8 hefty), buckler (d4, A1), mail coif (A1)","Tattoos (see below)","Pale steed (VIG 8, CLA 12, SPI 5, 3GD)"],"ability":{"name":"Mosstongue","text":"Speak with uncut stones and particularly old trees. If you push them for too much knowledge they rebuke you, shunning you for the rest of the day."},"passion":{"name":"Naturality","text":"Restore SPI when you reject an opportunity to sleep indoors, sleeping in nature instead."}},"pt":{"property":["Clava de galho (d8 pesada), broquel (d4, A1), coifa de malha (A1)","Tatuagens (veja abaixo)","Corcel pálido (VIG 8, CLA 12, ESP 5, 3GD)"],"ability":{"name":"Língua de Musgo","text":"Fale com pedras brutas e árvores particularmente antigas. Se você pressioná-las por conhecimento demais, elas o repreendem, ignorando-o pelo resto do dia."},"passion":{"name":"Naturalidade","text":"Restaure ESP quando rejeitar uma oportunidade de dormir sob um teto, dormindo na natureza em vez disso."}}},{"id":"1-6","d6":1,"d12":6,"name":{"en":"The War Knight","pt":"O Cavaleiro da Guerra"},"en":{"property":["Special polearm (d8, long, see below), gambeson (A1), splint (A1), helm (A1, see below)","Whalebone chess set (and some skill)","Stocky steed (VIG 15, CLA 8, SPI 5, 2GD)"],"ability":{"name":"Battle Awareness","text":"When fighting in a combat with at least 3 combatants on each side all your Gambits count as Strong Gambits."},"passion":{"name":"Duty","text":"Restore SPI when you answer the call for martial service under a superior."}},"pt":{"property":["Arma de haste especial (d8, longa, veja abaixo), gambeson (A1), talas (A1), elmo (A1, veja abaixo)","Jogo de xadrez de osso de baleia (e alguma habilidade)","Corcel atarracado (VIG 15, CLA 8, ESP 5, 2GD)"],"ability":{"name":"Consciência de Batalha","text":"Ao lutar em um combate com pelo menos 3 combatentes de cada lado, todas as suas Façanhas contam como Façanhas Fortes."},"passion":{"name":"Dever","text":"Restaure ESP quando atender ao chamado para o serviço marcial sob um superior."}}},{"id":"1-7","d6":1,"d12":7,"name":{"en":"The Willow Knight","pt":"O Cavaleiro do Salgueiro"},"en":{"property":["Old sword (d8 hefty) and half-shield (A1), gambeson (A1)","Youthful energy (use once only to treat a Mortal Wound as a normal Wound)","Cautious steed (VIG 10, CLA 15, SPI 5, 2GD)"],"ability":{"name":"Bend with the Wind","text":"When you use a Gambit to Move you count as having Armour 4 until your next turn. This does not stack with your actual armour."},"passion":{"name":"Doubt","text":"Restore SPI when you defer to somebody more senior than you, even though you disagree."}},"pt":{"property":["Espada velha (d8 pesada) e meio-escudo (A1), gambeson (A1)","Energia juvenil (use apenas uma vez para tratar um Ferimento Mortal como um Ferimento normal)","Corcel cauteloso (VIG 10, CLA 15, ESP 5, 2GD)"],"ability":{"name":"Curvar-se com o Vento","text":"Quando você usa uma Façanha para Mover-se, conta como tendo Armadura 4 até o seu próximo turno. Isso não acumula com sua armadura real."},"passion":{"name":"Dúvida","text":"Restaure ESP quando ceder a alguém mais experiente que você, mesmo discordando."}}},{"id":"1-8","d6":1,"d12":8,"name":{"en":"The Gilded Knight","pt":"O Cavaleiro Dourado"},"en":{"property":["Great mace (d10 long)","Gambeson (A1), gold cloaked plate (A1), gold-masked helm (A1, opponents who know the value of gold have their first ever Attack against you Impaired)","Majestic charger (VIG 12, CLA 9, SPI 12, 4GD, d6 trample)"],"ability":{"name":"Martyr-in-Waiting","text":"Use as a reaction to being Mortally Wounded. Allies fighting with you regain d6GD and get +d12 against your attacker for the combat."},"passion":{"name":"Pride","text":"Restore SPI when you take personal credit for a great victory."}},"pt":{"property":["Grande maça (d10 longa)","Gambeson (A1), placas com manto dourado (A1), elmo com máscara de ouro (A1, oponentes que conhecem o valor do ouro têm seu primeiro Ataque contra você Prejudicado)","Corcel de guerra majestoso (VIG 12, CLA 9, ESP 12, 4GD, d6 atropelar)"],"ability":{"name":"Mártir em Espera","text":"Use como reação ao ser Mortalmente Ferido. Aliados lutando com você recuperam d6 de GD e recebem +d12 contra seu atacante pelo resto do combate."},"passion":{"name":"Orgulho","text":"Restaure ESP quando assumir o crédito pessoal por uma grande vitória."}}},{"id":"1-9","d6":1,"d12":9,"name":{"en":"The Saddle Knight","pt":"O Cavaleiro da Sela"},"en":{"property":["Beloved steed (VIG 12, CLA 15, SPI 7, 4GD, see below)","Fine saddle and tack (you can never be dismounted)","3 Rider’s Axes (d6 +d6 when mounted, can be thrown), mail (A1) and rider’s plate (A1 when mounted)"],"ability":{"name":"Song of the Steed","text":"Speak in a voice comprehensible to horses. They need reasoning with, but are inclined to trust you."},"passion":{"name":"Certainty","text":"Restore SPI when you prove somebody wrong."}},"pt":{"property":["Montaria amada O Cavaleiro da Sela Uma montaria perfeita não é nem selvagem nem domada Como um só, um risco veloz pelo verde indomado (VIG 12, CLA 15, ESP 7, 4GD, veja abaixo)","Sela e arreios finos (você nunca pode ser desmontado)","3 Machados de Ginete (d6 +d6 quando montado, podem ser arremessados), malha (A1) e placas de ginete (A1 quando montado)"],"ability":{"name":"Canção da Montaria","text":"Fale com uma voz compreensível para cavalos. Eles precisam ser convencidos com argumentos, mas tendem a confiar em você."},"passion":{"name":"Certeza","text":"Restaure ESP quando provar que alguém está errado."}}},{"id":"1-10","d6":1,"d12":10,"name":{"en":"The Riddle Knight","pt":"O Cavaleiro do Enigma"},"en":{"property":["Twisted bow (d6 long), light mail (A1) with embroidered cloak","Moon pendant (grants the wearer a false form under moonlight, see below, rolling each night)","Shadowy horse (VIG 8, CLA 15, SPI 5, 2GD, very quiet)"],"ability":{"name":"Layered Words","text":"Speak, but choose two different meanings, as different as you wish, even total opposites. Choose which meaning each listener takes from the words."},"passion":{"name":"Integrity","text":"Restore SPI when you discredit somebody unworthy of their position."}},"pt":{"property":["Arco retorcido (d6 longo), malha leve (A1) com manto bordado","Pingente da lua (concede ao usuário uma forma falsa sob o luar, veja abaixo, rolando a cada noite)","Cavalo sombrio (VIG 8, CLA 15, ESP 5, 2GD, muito silencioso)"],"ability":{"name":"Palavras em Camadas","text":"Fale, mas escolha dois significados diferentes, tão diferentes quanto desejar, até mesmo opostos totais. Escolha qual significado cada ouvinte extrai das palavras."},"passion":{"name":"Integridade","text":"Restaure ESP quando desacreditar alguém indigno de sua posição."}}},{"id":"1-11","d6":1,"d12":11,"name":{"en":"The Talon Knight","pt":"O Cavaleiro da Garra"},"en":{"property":["Hookhammer (d8 hefty, +d8 dropping from above), shield-gauntlet (d6, A1), helm (A1)","Loyal bird (VIG 5, CLA 10, SPI 5, 4GD, d4 talons, see below)","Old steed (VIG 8, CLA 8, SPI 7, 2GD)"],"ability":{"name":"Flockbond","text":"See through the eyes of your bird, and learn the local knowledge of any prey it eats."},"passion":{"name":"Regret","text":"Restore SPI when you burn a part of the past."}},"pt":{"property":["Martelo-gancho (d8 pesado, +d8 caindo de cima), manopla-escudo (d6, A1), elmo (A1)","Ave leal (VIG 5, CLA 10, ESP 5, 4GD, d4 garras, veja abaixo)","Corcel velho (VIG 8, CLA 8, ESP 7, 2GD)"],"ability":{"name":"Elo do Bando","text":"Veja através dos olhos de sua ave e aprenda o conhecimento local de qualquer presa que ela devorar."},"passion":{"name":"Arrependimento","text":"Restaure ESP quando queimar uma parte do passado."}}},{"id":"1-12","d6":1,"d12":12,"name":{"en":"The Barbed Knight","pt":"O Cavaleiro Farpado"},"en":{"property":["Jagged spear (d8 hefty, +d8 against a target you have Wounded or Scarred), red cloaked mail (A1)","Hunting bow (d6 long)","Vicious charger (VIG 12, CLA 8, SPI 5, 3GD, d6 trample)"],"ability":{"name":"The Red Hunt","text":"Infuse a target’s blood into an arrow to give it +d12 against the target. You can also taste a small amount of the blood to get a glimpse of their location."},"passion":{"name":"Apathy","text":"Restore SPI when you reject a call for comfort."}},"pt":{"property":["Lança denteada (d8 pesada, +d8 contra um alvo que você tenha Ferido ou Cicatrizado), malha de manto vermelho (A1)","Arco de caça (d6 longo)","Corcel de guerra feroz (VIG 12, CLA 8, ESP 5, 3GD, d6 atropelar)"],"ability":{"name":"A Caçada Vermelha","text":"Infundir o sangue de um alvo em uma flecha para conceder a ela +d12 contra o alvo. Você também pode provar uma pequena quantidade do sangue para ter um vislumbre da localização dele."},"passion":{"name":"Apatia","text":"Restaure ESP quando rejeitar um pedido de consolo."}}},{"id":"2-1","d6":2,"d12":1,"name":{"en":"The Trail Knight","pt":"O Cavaleiro da Trilha"},"en":{"property":["Crow-beak axe (d8 hefty) and beaten gambeson (A1)","Sanguine lens (traces of blood appear obvious when viewed through this)","Serene steed (VIG 10, CLA 13, SPI 5, 3GD)"],"ability":{"name":"Strands of Past","text":"By studying the ground for a whole Phase you can ask a single yes or no question about what happened here in the past few days."},"passion":{"name":"Fear","text":"Restore SPI when refusing to go into the dark."}},"pt":{"property":["Machado bico-de-corvo (d8 pesado) e gambeson surrado (A1)","Lente sanguínea (vestígios de sangue parecem óbvios quando vistos através dela)","Corcel sereno (VIG 10, CLA 13, ESP 5, 3GD)"],"ability":{"name":"Fios do Passado","text":"Ao estudar o chão por uma Fase inteira, você pode fazer uma única pergunta de sim ou não sobre o que aconteceu aqui nos últimos dias."},"passion":{"name":"Medo","text":"Restaure ESP ao se recusar a entrar na escuridão."}}},{"id":"2-2","d6":2,"d12":2,"name":{"en":"The Amber Knight","pt":"O Cavaleiro de Âmbar"},"en":{"property":["Ancient greatblade (2d10 slow) and even more ancient mail (A1)","Amber amulet (if placed in a fire, carries its warmth for a whole day)","Loyal steed (VIG 10, CLA 10, SPI 5, 3GD, d6 trample)"],"ability":{"name":"Patient Strike","text":"Make a melee Attack when you have not moved this turn. +d10 to the Attack. Ignore the target’s Armour and immunities of any sort. If this fails to defeat the opponent, take d6 Damage yourself."},"passion":{"name":"Avarice","text":"Restore SPI when you gain significant wealth."}},"pt":{"property":["Montante ancestral (2d10 lento) e malha ainda mais antiga (A1)","Amuleto de âmbar (se colocado no fogo, mantém seu calor por um dia inteiro)","Montaria leal (VIG 10, CLA 10, ESP 5, 3GD, d6 atropelar)"],"ability":{"name":"Golpe Paciente","text":"Faça um Ataque corpo a corpo quando não tiver se movido neste turno. +d10 no Ataque. Ignore a Armadura do alvo e imunidades de qualquer tipo. Se isso falhar em derrotar o oponente, sofra d6 de Dano você mesmo."},"passion":{"name":"Avareza","text":"Restaure ESP quando conquistar riqueza significativa."}}},{"id":"2-3","d6":2,"d12":3,"name":{"en":"The Horde Knight","pt":"O Cavaleiro da Horda"},"en":{"property":["Blunt sword (d8 hefty), ringed mail (A1)","A taste of home (see below, restock each new Season)","Beastly steed (VIG 15, CLA 7, SPI 5, 3GD, d6 trample)"],"ability":{"name":"Pack Tactics","text":"Use before attacking with at least one ally. You may combine any number of dice into larger dice with a value equal to the total of the combined dice, to a maximum of d12 Damage. For example, combining a d4 and a d8 into a d12."},"passion":{"name":"Prestige","text":"Restore SPI when you take credit for the deeds of another."}},"pt":{"property":["Espada cega (d8 pesada), malha anelada (A1)","Um gosto de lar (veja abaixo, reabastece a cada nova Estação)","Montaria bestial (VIG 15, CLA 7, ESP 5, 3GD, d6 atropelar)"],"ability":{"name":"Táticas de Matilha","text":"Use antes de atacar com pelo menos um aliado. Você pode combinar qualquer número de dados em dados maiores com valor igual ao total dos dados combinados, até o máximo de d12 de Dano. Por exemplo, combinando um d4 e um d8 em um d12."},"passion":{"name":"Prestígio","text":"Restaure ESP quando assumir o crédito pelos feitos de outrem."}}},{"id":"2-4","d6":2,"d12":4,"name":{"en":"The Emerald Knight","pt":"O Cavaleiro de Esmeralda"},"en":{"property":["Branchspear (d8 hefty, when stabbed into a tree it is immovable by anyone but you)","Cloaked mail (A1 in verdant environments only), shield (d4, A1)","Sable steed (VIG 10, CLA 14, SPI 5, 4GD)"],"ability":{"name":"Fade to Green","text":"Use when hiding still and silent in greenery. You cannot be found by any means. While hiding you can only perform a specific type of action without revealing yourself, but also benefit from a heightened sense (see below)."},"passion":{"name":"Elegance","text":"Restore SPI when you leave a place more beautiful than you found it."}},"pt":{"property":["Lança-galho (d8 pesada, quando cravada em uma árvore torna-se imóvel para qualquer um exceto você)","Malha com manto (A1 apenas em ambientes verdejantes), escudo (d4, A1)","Corcel negro (VIG 10, CLA 14, ESP 5, 4GD)"],"ability":{"name":"Desvanecer no Verde","text":"Use ao se esconder imóvel e silencioso na vegetação. Você não pode ser encontrado por nenhum meio. Enquanto escondido, só pode realizar um tipo específico de ação sem se revelar, mas também se beneficia de um sentido aguçado (veja abaixo)."},"passion":{"name":"Elegância","text":"Restaure ESP quando deixar um lugar mais belo do que o encontrou."}}},{"id":"2-5","d6":2,"d12":5,"name":{"en":"The Chain Knight","pt":"O Cavaleiro da Corrente"},"en":{"property":["Pronged mace (d8 hefty)","Oubliette mail (A1, wrapped in a long iron chain)","Tired steed (VIG 10, CLA 12, SPI 3, 3GD)"],"ability":{"name":"Will of the Irons","text":"Move a single chain that you hold as if it was a limb, using a single hand. You can lash out with both ends (d6 each), grasp opponents, and otherwise move it to your will."},"passion":{"name":"Abyss","text":"Restore SPI when sleeping underground in complete darkness."}},"pt":{"property":["Maça dentada (d8 pesada)","Malha de masmorra (A1, envolta em uma longa corrente de ferro)","Corcel cansado (VIG 10, CLA 12, ESP 3, 3GD)"],"ability":{"name":"Vontade dos Ferros","text":"Mova uma única corrente que você segura como se fosse um membro, usando uma única mão. Você pode chicotear com ambas as pontas (d6 cada), agarrar oponentes e movê-la conforme sua vontade."},"passion":{"name":"Abismo","text":"Restaure ESP ao dormir no subterrâneo em escuridão completa."}}},{"id":"2-6","d6":2,"d12":6,"name":{"en":"The Banner Knight","pt":"O Cavaleiro do Estandarte"},"en":{"property":["Banner-pike (d10 long, see below, lose d6 SPI if the banner ever falls to the ground in battle)","Spikehammer (d6) and ornate mail (A1).","Fat steed (VIG 10, CLA 8, SPI 5, 3GD, d6 trample)"],"ability":{"name":"Rousing Presence","text":"Use once per Attack when you are part of a group Attack, carrying a banner. You may reroll the entire pool of Attack dice once only."},"passion":{"name":"Sensitivity","text":"Restore SPI when receiving social approval."}},"pt":{"property":["Pique-estandarte (d10 longo, veja abaixo, perca d6 ESP se o estandarte cair no chão em batalha)","Martelo de espigão (d6) e malha ornamentada (A1).","Montaria gorda (VIG 10, CLA 8, ESP 5, 3GD, d6 atropelar)"],"ability":{"name":"Presença Inspiradora","text":"Use uma vez por Ataque quando fizer parte de um Ataque em grupo, portando um estandarte. Você pode rerrolar toda a parada de dados de Ataque apenas uma vez."},"passion":{"name":"Sensibilidade","text":"Restaure ESP ao receber aprovação social."}}},{"id":"2-7","d6":2,"d12":7,"name":{"en":"The Pigeon Knight","pt":"O Cavaleiro do Pombo"},"en":{"property":["Bitterglaive (d10 long, +d8 vs targets within their home)","Tattered mail (A1) with hooded cloak (can be used to vanish into a significantly large crowd)","Grey steed (VIG 7, CLA 8, SPI 5, 2GD, unmatched over long distance)"],"ability":{"name":"Wayfinder Sense","text":"Sense the direction in which a named destination lies, but not the best route to travel there. You cannot use this to find your lost home or the City."},"passion":{"name":"Inquisition","text":"Restore SPI when you wrangle the truth out of an uncooperative person."}},"pt":{"property":["Glaive-amarga (d10 longa, +d8 vs alvos dentro de seu próprio lar)","Malha esfarrapada (A1) com manto com capuz (pode ser usado para desaparecer em uma multidão significativamente grande)","Corcel cinzento (VIG 7, CLA 8, ESP 5, 2GD, inigualável em longas distâncias)"],"ability":{"name":"Sentido Desbravador","text":"Sinta a direção em que fica um destino nomeado, mas não a melhor rota para viajar até lá. Você não pode usar isso para encontrar seu lar perdido ou a Cidade."},"passion":{"name":"Inquisição","text":"Restaure ESP quando arrancar a verdade de uma pessoa pouco cooperativa."}}},{"id":"2-8","d6":2,"d12":8,"name":{"en":"The Shield Knight","pt":"O Cavaleiro do Escudo"},"en":{"property":["Dull sword (2d6 hefty), tattered gambeson (A1) and cracked shield (d4, A1)","Soothing salve (you prepare enough for one use each day, restores VIG, see below)","Untested steed (VIG 12, CLA 8, SPI 4, 2GD)"],"ability":{"name":"Death Ward","text":"Use when a nearby ally would take a Mortal Wound or be killed outright. You take a Mortal Wound instead."},"passion":{"name":"Mortality","text":"Restore SPI when you see an ally suffer a Mortal Wound."}},"pt":{"property":["Espada cega (2d6 pesada), gambeson esfarrapado (A1) e escudo rachado (d4, A1)","Unguento calmante (você prepara o suficiente para um uso por dia, restaura VIG, veja abaixo)","Corcel inexperiente (VIG 12, CLA 8, ESP 4, 2GD)"],"ability":{"name":"Proteção Contra a Morte","text":"Use quando um aliado próximo sofreria um Ferimento Mortal ou seria morto instantaneamente. Você sofre um Ferimento Mortal em seu lugar."},"passion":{"name":"Mortalidade","text":"Restaure ESP quando vir um aliado sofrer um Ferimento Mortal."}}},{"id":"2-9","d6":2,"d12":9,"name":{"en":"The Whip Knight","pt":"O Cavaleiro do Chicote"},"en":{"property":["Spiny mace (d8 hefty) and whip (d6)","Strange herbs (different effect each time, see below. Enough for one dose each day. Effects wear off after an hour, but Virtue Loss remains)","Pampered steed (VIG 10, CLA 8, SPI 5, 2GD)"],"ability":{"name":"Pain Strike","text":"Make a melee Attack on your own. Damage is applied to GD as normal, but to SPI in place of VIG. If the target loses half or more of their SPI from this Attack they lie broken before you."},"passion":{"name":"Reverence","text":"Restore SPI when offering respectful homage to the dead."}},"pt":{"property":["Maça espinhosa (d8 pesada) e chicote (d6)","Ervas estranhas (efeito diferente a cada vez, veja abaixo. Suficiente para uma dose por dia. Os efeitos passam após uma hora, mas a Perda de Virtude permanece)","Corcel mimado (VIG 10, CLA 8, ESP 5, 2GD)"],"ability":{"name":"Golpe Doloroso","text":"Faça um Ataque corpo a corpo sozinho. O Dano é aplicado à GD normalmente, mas ao ESP em vez do VIG. Se o alvo perder metade ou mais de seu ESP com este Ataque, ele cai alquebrado diante de você."},"passion":{"name":"Reverência","text":"Restaure ESP ao prestar homenagem respeitosa aos mortos."}}},{"id":"2-10","d6":2,"d12":10,"name":{"en":"The Seal Knight","pt":"O Cavaleiro do Selo"},"en":{"property":["Stout halberd (d10 long), gambeson (A1), siege plate (A1, when the wearer braces against a door it cannot be breached)","3 runic scrolls (see below, can only be read by Seers, who value them greatly)","Dusty steed (VIG 10, CLA 8, SPI 5, 4GD)"],"ability":{"name":"Seal of Binding","text":"Mark a weapon, shield, or piece of armour belonging to a non-Knight with your seal. They can use Smite or Deny as if they were a Knight, but then the seal is removed."},"passion":{"name":"Modesty","text":"Restore SPI when refusing a reward."}},"pt":{"property":["Alabarda robusta (d10 longa), gambeson (A1), placas de cerco (A1, quando o usuário se escora contra uma porta, ela não pode ser arrombada)","3 pergaminhos rúnicos (veja abaixo, só podem ser lidos por Videntes, que os valorizam muito)","Corcel empoeirado (VIG 10, CLA 8, ESP 5, 4GD)"],"ability":{"name":"Selo de Vinculação","text":"Marque uma arma, escudo ou peça de armadura pertencente a um não-Cavaleiro com o seu selo. Ele pode usar Golpear com Fúria ou Negar como se fosse um Cavaleiro, mas então o selo é removido."},"passion":{"name":"Modéstia","text":"Restaure ESP ao recusar uma recompensa."}}},{"id":"2-11","d6":2,"d12":11,"name":{"en":"The Horn Knight","pt":"O Cavaleiro do Chifre"},"en":{"property":["Antler-halberd (d8 long, +d10 vs horned or antlered opponents) and bow (d6 long)","Wild Horn (see below)","Rusty warhorse (VIG 13, CLA 6, SPI 5, 2GD, d6 trample)"],"ability":{"name":"Carnage Fanfare","text":"Blow a Wild Horn in battle. For the rest of this battle any VIG lost through Damage is doubled. This affects all in the battle, whether they hear the horn or not."},"passion":{"name":"Bluntness","text":"Restore SPI when you move the conversation in a way that somebody is avoiding."}},"pt":{"property":["Alabarda de galhada (d8 longa, +d10 vs oponentes com chifres ou galhadas) e arco (d6 longo)","Trombeta Selvagem (veja abaixo)","Cavalo de guerra enferrujado (VIG 13, CLA 6, ESP 5, 2GD, d6 atropelar)"],"ability":{"name":"Fanfarra da Carnificina","text":"Sopre uma Trombeta Selvagem em batalha. Pelo resto desta batalha, qualquer VIG perdido por Dano é dobrado. Isso afeta todos na batalha, quer ouçam a trombeta ou não."},"passion":{"name":"Franqueza","text":"Restaure ESP quando conduzir a conversa para um rumo que alguém está evitando."}}},{"id":"2-12","d6":2,"d12":12,"name":{"en":"The Dove Knight","pt":"O Cavaleiro da Pomba"},"en":{"property":["Stout blade (2d6 hefty), gambeson (A1), and winged scale (A1, can’t fly, but see below)","Bright weeds (create a cool glow when crushed to a powder, restock each new Season)","Mountain steed (VIG 14, CLA 5, SPI 5, 2GD, sure-footed on rocky ground)"],"ability":{"name":"Strike of Serenity","text":"Make a melee Attack against a wounded target. Get +d8 to the Attack. If this defeats the target then all allies restore SPI."},"passion":{"name":"Vengeance","text":"Restore SPI when achieving a worthy revenge."}},"pt":{"property":["Lâmina robusta (2d6 pesada), gambeson (A1) e brunea alada (A1, não pode voar, mas veja abaixo)","Ervas brilhantes (criam um brilho frio quando esmagadas até virarem pó, reabastecem a cada nova Estação)","Corcel da montanha (VIG 14, CLA 5, ESP 5, 2GD, passo firme em terreno rochoso)"],"ability":{"name":"Golpe da Serenidade","text":"Faça um Ataque corpo a corpo contra um alvo ferido. Receba +d8 no Ataque. Se isso derrotar o alvo, todos os aliados restauram ESP."},"passion":{"name":"Vingança","text":"Restaure ESP ao alcançar uma vingança digna."}}},{"id":"3-1","d6":3,"d12":1,"name":{"en":"The Story Knight","pt":"O Cavaleiro das Histórias"},"en":{"property":["Crook-blade (d10 long), mail (A1), bronze- studded brigandine (A1)","Book of stories (something for everyone, see below for a random tale)","Sinister steed (VIG 10, CLA 14, SPI 5, 3GD)"],"ability":{"name":"Weaver of Fate","text":"Just before night falls, tell a story related to a nearby place, noting two details past, present, or future. The Referee secretly chooses one of them to become truth. This can only be performed once per location."},"passion":{"name":"Showmanship","text":"Restore SPI when you deliberately draw unwanted attention."}},"pt":{"property":["Lâmina-cajado (d10 longa), malha (A1), brigantina cravejada de bronze (A1)","Livro de histórias (algo para todos, veja abaixo para um conto aleatório)","Corcel sinistro (VIG 10, CLA 14, ESP 5, 3GD)"],"ability":{"name":"Tecelão do Destino","text":"Pouco antes do anoitecer, conte uma história relacionada a um lugar próximo, mencionando dois detalhes do passado, presente ou futuro. O Árbitro escolhe secretamente um deles para se tornar verdade. Isso só pode ser feito uma vez por local."},"passion":{"name":"Teatralidade","text":"Restaure ESP quando atrair deliberadamente atenção indesejada."}}},{"id":"3-2","d6":3,"d12":2,"name":{"en":"The Turtle Knight","pt":"O Cavaleiro da Tartaruga"},"en":{"property":["Beakhammer (d6), battered tower shield (d4, A1)","Drinking horn (makes even disgusting liquids taste good, see below)","Squat steed (VIG 14, CLA 5, SPI 6, 2GD)"],"ability":{"name":"Unbreakable Shell","text":"Use at the start of your turn. You cannot move, but double the Armour score of your shield and gain +d6 when attacking with a shield."},"passion":{"name":"Wellrestedness","text":"Restore SPI when you sleep for two consecutive Phases."}},"pt":{"property":["Martelo-bico (d6), escudo de torre surrado (d4, A1)","Chifre de beber (faz até líquidos repugnantes terem bom gosto, veja abaixo)","Corcel atarracado (VIG 14, CLA 5, ESP 6, 2GD)"],"ability":{"name":"Casco Inquebrável","text":"Use no início do seu turno. Você não pode se mover, mas dobra o valor de Armadura do seu escudo e ganha +d6 ao atacar com o escudo."},"passion":{"name":"Bom Descanso Restaure ESP quando","text":"dormir por duas Fases consecutivas."}}},{"id":"3-3","d6":3,"d12":3,"name":{"en":"The Key Knight","pt":"O Cavaleiro da Chave"},"en":{"property":["Horned axe (d8 hefty), kite shield (A1 d4)","Ring of keys (for any lock there’s a 1-in-3 chance you can find a key that fits) and bag of ill-gotten gains (see below)","Jittery steed (VIG 12, CLA 10, SPI 3, 3GD)"],"ability":{"name":"Retroactive Forethought","text":"Once per day, produce a common item from your backpack that you could have reasonably acquired at a recent point."},"passion":{"name":"Distraction","text":"Restore SPI when you abandon a set plan."}},"pt":{"property":["Machado chifrudo (d8 pesado), escudo gota (A1 d4)","Molho de chaves (para qualquer fechadura há 1 em 3 de chance de você encontrar uma chave que sirva) e saco de ganhos ilícitos (veja abaixo)","Corcel arisco (VIG 12, CLA 10, ESP 3, 3GD)"],"ability":{"name":"Previsão Retroativa","text":"Uma vez por dia, retire um item comum de sua mochila que você poderia razoavelmente ter adquirido recentemente."},"passion":{"name":"Distração","text":"Restaure ESP quando abandonar um plano estabelecido."}}},{"id":"3-4","d6":3,"d12":4,"name":{"en":"The Moat Knight","pt":"O Cavaleiro do Fosso"},"en":{"property":["Spiked flail (d10, long) and barbed mail (A1, anyone trying to grab or hold you takes d6 Damage)","Moat shovel (any hole dug with this immediately begins to fill with water, stopping when full)","Difficult steed (VIG 12, CLA 6, SPI 6, 2GD, see below)"],"ability":{"name":"Wading Stance","text":"Gain 1 Armour and +d6 to all attacks when fighting in at least waist-high water."},"passion":{"name":"Filth","text":"Restore SPI when you become utterly filthy."}},"pt":{"property":["Mangual espinhoso (d10, longo) e malha farpada (A1, qualquer um que tente agarrar ou segurar você sofre d6 de Dano)","Pá de fosso (qualquer buraco cavado com ela começa imediatamente a se encher de água, parando quando cheio)","Montaria difícil (VIG 12, CLA 6, ESP 6, 2GD, veja abaixo)"],"ability":{"name":"Postura de Vau","text":"Ganhe 1 de Armadura e +d6 em todos os ataques ao lutar em água pelo menos na altura da cintura."},"passion":{"name":"Imundície","text":"Restaure ESP quando ficar completamente imundo."}}},{"id":"3-5","d6":3,"d12":5,"name":{"en":"The Boulder Knight","pt":"O Cavaleiro do Rochedo"},"en":{"property":["Siege hammer (d10 long), mail (A1), and fancy plate (A1, see below)","Hand-written book “Of Time-Tested Guidance in the Construction and Destruction of Fortresses, Ramparts, and Castles”.","Well-fed steed (VIG 14, CLA 8, SPI 6, 3GD)"],"ability":{"name":"Unstoppable Dash","text":"When you are in motion you cannot be stopped, but sustain d12 Damage if breaking through a solid wall or object. You cannot sustain this motion for long distances."},"passion":{"name":"Strength","text":"Restore SPI when you complete a physical task that somebody else was struggling with."}},"pt":{"property":["Martelo de cerco (d10 longo), malha (A1) e placas adornadas (A1, veja abaixo)","Livro manuscrito “Da Orientação Comprovada pelo Tempo na Construção e Destruição de Fortalezas, Muralhas e Castelos”.","Corcel bem-alimentado (VIG 14, CLA 8, ESP 6, 3GD)"],"ability":{"name":"Investida Imparável","text":"Quando está em movimento você não pode ser detido, mas sofre d12 de Dano se atravessar uma parede ou objeto sólido. Você não pode sustentar esse movimento por longas distâncias."},"passion":{"name":"Força","text":"Restaure ESP quando concluir uma tarefa física com a qual outra pessoa estava tendo dificuldade."}}},{"id":"3-6","d6":3,"d12":6,"name":{"en":"The Tankard Knight","pt":"O Cavaleiro da Caneca"},"en":{"property":["Eagle axe (d8 hefty), roundshield (d4, A1), mail shirt (A1)","Scar from a friend betrayed (see below)","Aggressive charger (VIG 14, CLA 5, SPI 6, 2GD, d8 trample)"],"ability":{"name":"Humble Glamourie","text":"After eating and drinking with somebody for a few hours they consider you trustworthy enough to speak openly about anything you ask about. The next day they come to their senses and realise if they revealed too much."},"passion":{"name":"Revelry","text":"Restore SPI when socially overindulging."}},"pt":{"property":["Machado-águia (d8 pesado), escudo redondo (d4, A1), camisa de malha (A1)","Cicatriz de um amigo traído (veja abaixo)","Corcel de guerra agressivo (VIG 14, CLA 5, ESP 6, 2GD, d8 atropelar)"],"ability":{"name":"Encanto Humilde","text":"Após comer e beber com alguém por algumas horas, a pessoa o considera confiável o bastante para falar abertamente sobre qualquer coisa que você perguntar. No dia seguinte, ela cai em si e percebe se revelou demais."},"passion":{"name":"Folia","text":"Restaure ESP ao cometer excessos sociais."}}},{"id":"3-7","d6":3,"d12":7,"name":{"en":"The Owl Knight","pt":"O Cavaleiro da Coruja"},"en":{"property":["Blade-staff (2d8 long) and ringmail (A1)","Sack of books (1-in-2 chance you have a small snippet of information on any particular topic at hand, otherwise you find a miscellaneous tome, as below)","Peaceful steed (VIG 10, CLA 10, SPI 6, 4GD)"],"ability":{"name":"Arboreal Archive","text":"Spend a Phase running hands over a tree to access its memory, seeing anything that happened under its shade or over its roots."},"passion":{"name":"Alertness","text":"Restore SPI when you spot an ambush, trap, or surprise attack."}},"pt":{"property":["Bastão-lâmina (2d8 longo) e malha de anéis (A1)","Saco de livros (1 em 2 de chance de ter um pequeno trecho de informação sobre qualquer tópico específico em mãos; caso contrário, você encontra um tomo diverso, como abaixo)","Corcel pacífico (VIG 10, CLA 10, ESP 6, 4GD)"],"ability":{"name":"Arquivo Arbóreo","text":"Gaste uma Fase passando as mãos sobre uma árvore para acessar sua memória, vendo qualquer coisa que tenha acontecido sob sua sombra ou sobre suas raízes."},"passion":{"name":"Vigilância","text":"Restaure ESP quando avistar uma emboscada, armadilha ou ataque surpresa."}}},{"id":"3-8","d6":3,"d12":8,"name":{"en":"The Hooded Knight","pt":"O Cavaleiro Encapuzado"},"en":{"property":["Glaive (d10 long), 3 throwing axes (d6)","Cloak and hood (see below, while fully cloaked and hooded, people will see you in the moment, but have no memory of you once you pass from sight)","Modest steed (VIG 10, CLA 9, SPI 5, 4GD)"],"ability":{"name":"Unnoticed Deed","text":"Once per day you can retroactively declare an action that you took earlier that day, such as giving instructions to an ally, or gathering a specific piece of information. This cannot be used to acquire new items."},"passion":{"name":"Anonymity","text":"Restore SPI when somebody believes in a false identity you are portraying."}},"pt":{"property":["Glaive (d10 longa), 3 machados de arremesso (d6)","Manto e capuz (veja abaixo; enquanto estiver totalmente coberto pelo manto e capuz, as pessoas o verão no momento, mas não terão memória de você assim que sair de vista)","Corcel modesto (VIG 10, CLA 9, ESP 5, 4GD)"],"ability":{"name":"Feito Despercebido","text":"Uma vez por dia, você pode declarar retroativamente uma ação que realizou mais cedo naquele dia, como dar instruções a um aliado ou coletar uma informação específica. Isso não pode ser usado para adquirir novos itens."},"passion":{"name":"Anonimato","text":"Restaure ESP quando alguém acreditar em uma identidade falsa que você esteja interpretando."}}},{"id":"3-9","d6":3,"d12":9,"name":{"en":"The Lance Knight","pt":"O Cavaleiro da Lança"},"en":{"property":["Lance (d10 long or hefty if mounted), spiked mace (d8 hefty), kite shield (d4, A1)","Mystic sight (you can see something you shouldn't be able to, see below)","Weary charger (VIG 14, CLA 6, SPI 4, 3GD, d6 trample)"],"ability":{"name":"Shattering Charge","text":"Once per day, make a solo mounted charging Attack with a lance. The Attack gains +d12, Blast, and Gambits caused by the Attack count as strong. The lance is shattered."},"passion":{"name":"Adventure","text":"Restore SPI when you enter a Myth Hex."}},"pt":{"property":["Lança (d10 longa ou pesada se montado), maça espinhosa (d8 pesada), escudo gota (d4, A1)","Visão mística (você consegue ver algo que não deveria ser capaz de ver, veja abaixo)","Corcel de guerra cansado (VIG 14, CLA 6, ESP 4, 3GD, d6 atropelar)"],"ability":{"name":"Investida Estilhaçante","text":"Uma vez por dia, faça um Ataque de investida montado solo com uma lança. O Ataque ganha +d12, Explosão, e Façanhas causadas pelo Ataque contam como Fortes. A lança se estilhaça."},"passion":{"name":"Aventura","text":"Restaure ESP quando entrar em um Hexágono de Mito."}}},{"id":"3-10","d6":3,"d12":10,"name":{"en":"The Questing Knight","pt":"O Cavaleiro da Demanda"},"en":{"property":["Ancient sword (see below), kite shield (d4, A1), 3 javelins (d6)","Cold stone (can absorb a single ailment from the wielder before vanishing in a burning light, restock each new Season)","Reckless charger (VIG 14, CLA 6, SPI 6, 1GD, d8 trample)"],"ability":{"name":"Pledge Quest","text":"Swear a quest to somebody who cares. Until you complete the quest you cannot regain lost GD, but get +d12 on all attacks against those who stand in your way. Lose d12 SPI if you abandon the quest."},"passion":{"name":"Impetuosity","text":"Restore SPI when you are first to fight."}},"pt":{"property":["Espada ancestral (veja abaixo), escudo gota (d4, A1), 3 azagaias (d6)","Pedra fria (pode absorver uma única enfermidade do portador antes de desaparecer em uma luz ardente, reabastece a cada nova Estação)","Corcel de guerra imprudente (VIG 14, CLA 6, ESP 6, 1GD, d8 atropelar)"],"ability":{"name":"Voto de Demanda","text":"Jure uma demanda a alguém que se importe. Até concluir a demanda, você não pode recuperar GD perdida, mas recebe +d12 em todos os ataques contra aqueles que ficarem em seu caminho. Perca d12 ESP se abandonar a demanda."},"passion":{"name":"Impetuosidade","text":"Restaure ESP quando for o primeiro a lutar."}}},{"id":"3-11","d6":3,"d12":11,"name":{"en":"The Ring Knight","pt":"O Cavaleiro do Anel"},"en":{"property":["Long mace (d10 long), violet mail (A1)","Pair of rings (see below, can only be put on or removed at sunrise)","Aloof steed (VIG 11, CLA 8, SPI 7, 3GD, leaves no trail)"],"ability":{"name":"Unbreakable Circle","text":"Draw a circle in the ground, with yourself in the centre. Until you leave the circle, no other living being can enter or leave it."},"passion":{"name":"Respectfulness","text":"Restore SPI when returning something to its rightful owner after it was lost or taken."}},"pt":{"property":["Maça longa (d10 longa), malha violeta (A1)","Par de anéis (veja abaixo, só podem ser colocados ou removidos ao nascer do sol)","Montaria arisca (VIG 11, CLA 8, ESP 7, 3GD, não deixa rastro)"],"ability":{"name":"Círculo Inquebrável","text":"Desenhe um círculo no chão, com você mesmo no centro. Até que você saia do círculo, nenhum outro ser vivo pode entrar ou sair dele."},"passion":{"name":"Respeito","text":"Restaure ESP ao devolver algo ao seu legítimo dono após ter sido perdido ou tomado."}}},{"id":"3-12","d6":3,"d12":12,"name":{"en":"The Forge Knight","pt":"O Cavaleiro da Forja"},"en":{"property":["Bolt-guisarme (d10 long in melee or d10 slow ranged), gambeson (A1), scale (A1)","Scars from the forge (see below) and pots of forge dust (spreads irritating gas in the area when broken, Impairing attacks from within. You can make more anywhere with a forge)","Helmed steed (VIG 14, CLA 4, SPI 5, 4GD, d6 trample, A1)"],"ability":{"name":"Tempering Strike","text":"When you cause a Wound with a melee weapon, that weapon receives +d8 until the end of combat. This effect can stack."},"passion":{"name":"Burning","text":"Restore SPI when you are wounded by fire."}},"pt":{"property":["Guisarme-virote (d10 longa corpo a corpo ou d10 lenta à distância), gambeson (A1), brunea (A1)","Cicatrizes da forja (veja abaixo) e potes de pó de forja (espalham gás irritante na área quando quebrados, Prejudicando ataques vindos de dentro. Você pode fazer mais em qualquer lugar com uma forja)","Montaria com elmo (VIG 14, CLA 4, ESP 5, 4GD, d6 atropelar, A1)"],"ability":{"name":"Golpe de Têmpera","text":"Quando você causa um Ferimento com uma arma corpo a corpo, essa arma recebe +d8 até o fim do combate. Este efeito pode acumular."},"passion":{"name":"Ardor","text":"Restaure ESP quando for ferido por fogo."}}},{"id":"4-1","d6":4,"d12":1,"name":{"en":"The Rune Knight","pt":"O Cavaleiro da Runa"},"en":{"property":["Pillar of inscribed stone (2d10 slow), gambeson (A1), iron chestplate (A1)","Sealed crystal flask (see below, you know the effect. If smashed, find a new flask at the start of the next Season)","Muscular charger (VIG 13, CLA 8, SPI 5, 3GD, d8 trample)"],"ability":{"name":"Destinous Sigil","text":"At sunset, etch a cosmic rune somewhere secret on your person. Choose a number. When a die rolls that number you may adjust it to any other value on that die. This can be performed a number of times equal to the chosen number. A different number is chosen next sunset."},"passion":{"name":"Foresight","text":"Restore SPI when your prediction is proven to be correct."}},"pt":{"property":["Pilar de pedra inscrita (2d10 lento), gambeson (A1), peitoral de ferro (A1)","Frasco de cristal lacrado (veja abaixo, você conhece o efeito. Se quebrado, encontra um novo frasco no início da próxima Estação)","Corcel de guerra musculoso (VIG 13, CLA 8, ESP 5, 3GD, d8 atropelar)"],"ability":{"name":"Sigilo do Destino","text":"Ao pôr do sol, grave uma runa cósmica em algum lugar secreto do seu corpo. Escolha um número. Quando um dado rolar esse número, você pode ajustá-lo para qualquer outro valor naquele dado. Isso pode ser feito um número de vezes igual ao número escolhido. Um número diferente é escolhido no próximo pôr do sol."},"passion":{"name":"Previdência","text":"Restaure ESP quando sua previsão se provar correta."}}},{"id":"4-2","d6":4,"d12":2,"name":{"en":"The Gallows Knight","pt":"O Cavaleiro da Forca"},"en":{"property":["Neck-catcher (d10 long, Wounded targets are snared securely around the neck, provided they have one), salvaged armour (see below)","Titan beads (3 polished stones. When thrown they transform into a huge boulder mid-air, striking for d10 blast, restock each new Season)","Flea-bitten steed (VIG 9, CLA 7, SPI 4, 3GD)"],"ability":{"name":"Carrion’s Call","text":"Speak with scavenger creatures, and summon them to you. They’re only helpful if you’re providing them with food."},"passion":{"name":"Misery","text":"Restore SPI when you meet somebody new and complain to them about something."}},"pt":{"property":["Apanha-pescoço (d10 longo, alvos Feridos ficam presos com firmeza pelo pescoço, desde que tenham um), armadura recuperada (veja abaixo)","Contas titânicas (3 pedras polidas. Quando arremessadas, transformam-se em um imenso pedregulho no ar, atingindo com d10 explosão; reabastecem a cada nova Estação)","Corcel pulguento (VIG 9, CLA 7, ESP 4, 3GD)"],"ability":{"name":"Chamado da Carniça","text":"Fale com criaturas carniceiras e convoque-as até você. Elas só são prestativas se você lhes fornecer comida."},"passion":{"name":"Miséria","text":"Restaure ESP quando conhecer alguém novo e reclamar de algo para a pessoa."}}},{"id":"4-3","d6":4,"d12":3,"name":{"en":"The Tome Knight","pt":"O Cavaleiro do Tomo"},"en":{"property":["Heavy staff (d10 long), gambeson (A1), brass-studded brigandine (A1)","Perfect recall (you remember everything you have ever experienced perfectly, with a few limitations, see below)","Small steed (VIG 9, CLA 8, SPI 5, 2GD)"],"ability":{"name":"Dawn Contemplation","text":"At sunrise each day, choose any area of knowledge. You can ask the Referee three questions within this area, which they answer honestly with yes, no, or maybe if uncertain."},"passion":{"name":"Introversion","text":"Restore SPI when you refuse a formal social gathering, or leave early."}},"pt":{"property":["Bordão pesado (d10 longo), gambeson (A1), brigantina cravejada de latão (A1)","Memória perfeita (você se lembra perfeitamente de tudo o que já vivenciou, com algumas limitações; veja abaixo)","Corcel pequeno (VIG 9, CLA 8, ESP 5, 2GD)"],"ability":{"name":"Contemplação da Aurora","text":"Ao nascer do sol de cada dia, escolha qualquer área de conhecimento. Você pode fazer ao Árbitro três perguntas dentro dessa área, às quais ele responde honestamente com sim, não, ou talvez se for incerto."},"passion":{"name":"Introversão","text":"Restaure ESP quando recusar uma reunião social formal ou sair mais cedo."}}},{"id":"4-4","d6":4,"d12":4,"name":{"en":"The Meteor Knight","pt":"O Cavaleiro do Meteoro"},"en":{"property":["Elaborate trident (d10 long, see below), brass mail (A1)","Moon oil (when rubbed on an object you could lift it renders the object weightless until washed with water, restock each new Season)","Limping steed (VIG 12, CLA 8, SPI 5, 4GD, won’t be hurried)"],"ability":{"name":"Star Fall","text":"You never suffer Damage from falling, unless landing on something harmful. When you land from a fall of at least 12ft you may release a shockwave (d8 blast)."},"passion":{"name":"Authenticity","text":"Restore SPI when you reveal your identity or intentions at an inconvenient moment."}},"pt":{"property":["Tridente elaborado (d10 longo, veja abaixo), malha de latão (A1)","Óleo da lua (quando esfregado em um objeto que você conseguiria erguer, torna o objeto sem peso até ser lavado com água; reabastece a cada nova Estação)","Montaria manca (VIG 12, CLA 8, ESP 5, 4GD, não se deixa apressar)"],"ability":{"name":"Queda Estelar","text":"Você nunca sofre Dano de queda, a menos que caia sobre algo perigoso. Quando aterrissa de uma queda de pelo menos 3,5 metros, você pode liberar uma onda de choque (d8 explosão)."},"passion":{"name":"Autenticidade","text":"Restaure ESP quando revelar sua identidade ou intenções em um momento inconveniente."}}},{"id":"4-5","d6":4,"d12":5,"name":{"en":"The Gazer Knight","pt":"O Cavaleiro Observador"},"en":{"property":["Toothed blade (d8 hefty, +d8 against Seers), tapestry cloak (see below) over mail (A1)","Flickerlamp (a warm lantern that casts its shadows toward the nearest Seer)","Blueish steed (VIG 12, CLA 10, SPI 5, 3GD)"],"ability":{"name":"Glimpse of Fate","text":"Once per day you can undo a single action performed by you or your Company, declaring it was in fact a minor vision you received. Play as if it never happened."},"passion":{"name":"Respect","text":"Restore SPI when you yield to a Seer."}},"pt":{"property":["Lâmina dentada (d8 pesada, +d8 contra Videntes), manto de tapeçaria (veja abaixo) sobre malha (A1)","Lanterna trêmula (uma lanterna quente que projeta suas sombras na direção do Vidente mais próximo)","Corcel azulado (VIG 12, CLA 10, ESP 5, 3GD)"],"ability":{"name":"Vislumbre do Destino","text":"Uma vez por dia, você pode desfazer uma única ação realizada por você ou sua Companhia, declarando que na verdade foi uma pequena visão que você recebeu. Jogue como se ela nunca tivesse acontecido."},"passion":{"name":"Respeito","text":"Restaure ESP quando ceder a um Vidente."}}},{"id":"4-6","d6":4,"d12":6,"name":{"en":"The Mule Knight","pt":"O Cavaleiro da Mula"},"en":{"property":["Weighted longstaff (d10 long), polished chainmail (A1)","3 explosives (d8 blast, see below, restock each new Season)","Tall steed (VIG 14, CLA 7, SPI 6, 2GD)"],"ability":{"name":"Lowly Shroud","text":"At any time you may choose to have somebody observing you be utterly convinced that you are just a humble, unarmed peasant, and your steed a mule."},"passion":{"name":"Kindness","text":"Restore SPI when you stop an act of cruelty."}},"pt":{"property":["Bordão longo pesado (d10 longo), cota de malha polida (A1)","3 explosivos (d8 explosão, veja abaixo, reabastecem a cada nova Estação)","Corcel alto (VIG 14, CLA 7, ESP 6, 2GD)"],"ability":{"name":"Manto Humilde","text":"A qualquer momento, você pode fazer com que alguém que o observa fique totalmente convencido de que você é apenas um camponês humilde e desarmado, e seu corcel, uma mula."},"passion":{"name":"Bondade","text":"Restaure ESP quando impedir um ato de crueldade."}}},{"id":"4-7","d6":4,"d12":7,"name":{"en":"The Halo Knight","pt":"O Cavaleiro da Auréola"},"en":{"property":["Crescent axe (d8 hefty), ringmail (A1), kite shield (d4, A1)","Mistvial (when broken, thick mist rolls in over the whole Hex for the rest of the Phase. See below for repair requirements)","Wild steed (VIG 15, CLA 5, SPI 7, 3GD, will not be ridden by any but you)"],"ability":{"name":"Luminous Eruption","text":"Use once per Phase. A light source you are holding briefly illuminates the entire Hex and causes d12 Damage to nearby beings who live in darkness."},"passion":{"name":"Valour","text":"Restore SPI when you engage in combat against the odds."}},"pt":{"property":["Machado crescente (d8 pesado), malha de anéis (A1), escudo gota (d4, A1)","Frasco de névoa (quando quebrado, uma névoa espessa cobre todo o Hexágono pelo resto da Fase. Veja abaixo os requisitos de reparo)","Corcel selvagem (VIG 15, CLA 5, ESP 7, 3GD, não se deixará montar por ninguém além de você)"],"ability":{"name":"Erupção Luminosa","text":"Use uma vez por Fase. Uma fonte de luz que você esteja segurando ilumina brevemente todo o Hexágono e causa d12 de Dano a seres próximos que vivem na escuridão."},"passion":{"name":"Valor","text":"Restaure ESP quando entrar em combate contra as probabilidades."}}},{"id":"4-8","d6":4,"d12":8,"name":{"en":"The Iron Knight","pt":"O Cavaleiro de Ferro"},"en":{"property":["Cleavingblade (2d8 long, see below), mail (A1), plate pauldrons (A1)","Inscribed scabbard (shows a different scene each morning, hinting at the nearest Myth)","Dark steed (VIG 11, CLA 7, SPI 6, 3GD)"],"ability":{"name":"Heightened Sharpness","text":"When you perform a Strong Gambit with a bladed weapon you may choose one of the following as the effect, the target receiving a Save as normal: • Take a limb • Take a head if their GD is 0"},"passion":{"name":"Diligence","text":"Restore SPI when refusing a shortcut."}},"pt":{"property":["Lâmina-fendidora (2d8 longa, veja abaixo), malha (A1), ombreiras de placas (A1)","Bainha inscrita (mostra uma cena diferente a cada manhã, dando pistas sobre o Mito mais próximo)","Corcel escuro (VIG 11, CLA 7, ESP 6, 3GD)"],"ability":{"name":"Fio Aguçado Quando você realiza","text":"uma Façanha Forte com uma arma de lâmina, pode escolher um dos seguintes como efeito, recebendo o alvo uma Salvaguarda normalmente: • Decepar um membro • Decepar uma cabeça se a GD dele for 0"},"passion":{"name":"Diligência","text":"Restaure ESP ao recusar um atalho."}}},{"id":"4-9","d6":4,"d12":9,"name":{"en":"The Mirror Knight","pt":"O Cavaleiro do Espelho"},"en":{"property":["Hook-axe (d8 hefty), 3 throwing axes (d6), and round shield (d4, A1)","Hushingbell (those who hear the bell hear nothing else)","Faded steed (VIG 9, CLA 8, SPI 5, 3GD, you have memories together, see below)"],"ability":{"name":"Reflection of Blood","text":"When you are Wounded, the attacker suffers the same amount of VIG loss as you. When you are Scarred the attacker gets the same Scar."},"passion":{"name":"Egality","text":"Restore SPI when you give somebody else their fair share."}},"pt":{"property":["Machado-gancho (d8 pesado), 3 machados de arremesso (d6) e escudo redondo (d4, A1)","Sino-silenciador (aqueles que ouvem o sino não ouvem mais nada)","Corcel desbotado (VIG 9, CLA 8, ESP 5, 3GD, vocês têm memórias juntos, veja abaixo)"],"ability":{"name":"Reflexo de Sangue","text":"Quando você é Ferido, o atacante sofre a mesma quantidade de perda de VIG que você. Quando você recebe uma Cicatriz, o atacante recebe a mesma Cicatriz."},"passion":{"name":"Igualdade","text":"Restaure ESP quando der a outra pessoa sua parte justa."}}},{"id":"4-10","d6":4,"d12":10,"name":{"en":"The Dusk Knight","pt":"O Cavaleiro do Crepúsculo"},"en":{"property":["Longhammer (d10 long), 3 javelins (d6)","Pouch of wolfnuts (repellent to canines), poem on tattered parchment (see below)","Auburn steed (VIG 12, CLA 8, SPI 6, 2GD)"],"ability":{"name":"Sunder Memory","text":"When you Wound a target you can rob them of a single specific memory. If it is a Mortal Wound then you can remove all memory of a specific place, thing, person, or event."},"passion":{"name":"Temperance","text":"Restore SPI when you refuse a luxury."}},"pt":{"property":["Martelo longo (d10 longo), 3 azagaias (d6)","Bolsa de nozes-de-lobo (repelente para caninos), poema em pergaminho esfarrapado (veja abaixo)","Corcel ruivo (VIG 12, CLA 8, ESP 6, 2GD)"],"ability":{"name":"Partir a Memória","text":"Quando você Fere um alvo, pode roubar dele uma única memória específica. Se for um Ferimento Mortal, você pode remover toda a memória de um lugar, coisa, pessoa ou evento específico."},"passion":{"name":"Temperança","text":"Restaure ESP quando recusar um luxo."}}},{"id":"4-11","d6":4,"d12":11,"name":{"en":"The Coin Knight","pt":"O Cavaleiro da Moeda"},"en":{"property":["Morningstar (d8 hefty), roundshield (d4, A1), gambeson (A1), stone-studded brigandine (A1)","Jaunty flute (can only play a certain type of music, see below)","Arctic steed (VIG 14, CLA 8, SPI 7, 3GD, long coat turns white in winter)"],"ability":{"name":"Thrown to Chance","text":"Use instead of attacking normally. Flip a coin. Heads the target is killed, tails you are killed. This is final."},"passion":{"name":"Generosity","text":"Restore SPI when you give generously to somebody in need."}},"pt":{"property":["Maça-estrela (d8 pesada), escudo redondo (d4, A1), gambeson (A1), brigantina cravejada de pedra (A1)","Flauta alegre (só consegue tocar um certo tipo de música, veja abaixo)","Corcel ártico (VIG 14, CLA 8, ESP 7, 3GD, pelagem longa fica branca no inverno)"],"ability":{"name":"Lançado à Sorte","text":"Use em vez de atacar normalmente. Jogue uma moeda. Cara, o alvo é morto; coroa, você é morto. Isto é definitivo."},"passion":{"name":"Generosidade","text":"Restaure ESP quando doar generosamente a alguém necessitado."}}},{"id":"4-12","d6":4,"d12":12,"name":{"en":"The Mock Knight","pt":"O Cavaleiro do Escárnio"},"en":{"property":["War flail (d10 long)","Unnatural body (see below), concealed beneath plate suit (A1), hood, and clothes","Well-groomed steed (VIG 12, CLA 8, SPI 6, 2GD, a real horse)"],"ability":{"name":"Impression of Life","text":"You do not truly need air, food, water, sleep, warmth, or love, but you are compelled to play along when you are deprived of them."},"passion":{"name":"Imitation","text":"Restore SPI when you pass for human while under scrutiny."}},"pt":{"property":["Mangual de guerra (d10 longo)","Corpo antinatural (veja abaixo), oculto sob armadura de placas (A1), capuz e roupas","Montaria bem cuidada (VIG 12, CLA 8, ESP 6, 2GD, um cavalo de verdade)"],"ability":{"name":"Impressão de Vida","text":"Você não precisa realmente de ar, comida, água, sono, calor ou amor, mas é compelido a fingir que sim quando fica privado deles."},"passion":{"name":"Imitação","text":"Restaure ESP quando se passar por humano sob escrutínio."}}},{"id":"5-1","d6":5,"d12":1,"name":{"en":"The Mask Knight","pt":"O Cavaleiro da Máscara"},"en":{"property":["Splittingaxe (d10 long), mail (A1) with masked helm (A1, see below)","Star ink (writing only shows under starlight at night) and parchment","Silver steed (VIG 12, CLA 8, SPI 5, 4GD)"],"ability":{"name":"Thousand Faces","text":"You can assume the face of anybody you have touched, but your body and voice are unchanged."},"passion":{"name":"Vigilance","text":"Restore SPI when you prevent a betrayal."}},"pt":{"property":["Machado rachador (d10 longo), malha (A1) com elmo mascarado (A1, veja abaixo)","Tinta estelar (a escrita só aparece sob a luz das estrelas à noite) e pergaminho","Corcel prateado (VIG 12, CLA 8, ESP 5, 4GD)"],"ability":{"name":"Mil Faces","text":"Você pode assumir o rosto de qualquer pessoa que tenha tocado, mas seu corpo e voz permanecem inalterados."},"passion":{"name":"Vigilância","text":"Restaure ESP quando impedir uma traição."}}},{"id":"5-2","d6":5,"d12":2,"name":{"en":"The Bone Knight","pt":"O Cavaleiro do Osso"},"en":{"property":["Needledagger (d6, +d6 against armoured targets) and jagged buckler (d4, A1)","Box of bones (see below)","Marsh steed (VIG 12, CLA 8, SPI 5, 3GD, moves effortlessly on bog and marsh)"],"ability":{"name":"Bone Magnate","text":"When you make a genuine trade, a bone for a bone, learn something about the individual that the acquired bone came from, or something that they knew in life."},"passion":{"name":"Acumen","text":"Restore SPI when you come out better from a bargain."}},"pt":{"property":["Adaga-agulha (d6, +d6 contra alvos com armadura) e broquel denteado (d4, A1)","Caixa de ossos (veja abaixo)","Corcel do pântano (VIG 12, CLA 8, ESP 5, 3GD, move-se sem esforço em brejos e pântanos)"],"ability":{"name":"Magnata dos Ossos","text":"Quando você faz uma troca genuína, um osso por um osso, descobre algo sobre o indivíduo de quem veio o osso adquirido, ou algo que ele sabia em vida."},"passion":{"name":"Perspicácia","text":"Restaure ESP quando sair em vantagem de uma barganha."}}},{"id":"5-3","d6":5,"d12":3,"name":{"en":"The Salt Knight","pt":"O Cavaleiro do Sal"},"en":{"property":["Spined mace (d8 hefty), javelin (d6), coraline mail (A1)","Everflask (contains an endless supply of fresh water, see below)","Scaled steed (VIG 12, CLA 8, SPI 5, 3GD)"],"ability":{"name":"Inspire Ire","text":"Activate at the end of your turn. Until your next turn, any enemies that Attack targets other than you lose d10 SPI after the Attack is resolved."},"passion":{"name":"Mettle","text":"Restore SPI when accepting a non-combat challenge with the odds set against you."}},"pt":{"property":["Maça espinhosa (d8 pesada), azagaia (d6), malha coralina (A1)","Frasco eterno (contém um suprimento inesgotável de água fresca, veja abaixo)","Corcel escamoso (VIG 12, CLA 8, ESP 5, 3GD)"],"ability":{"name":"Inspirar Ira","text":"Ative no final do seu turno. Até o seu próximo turno, quaisquer inimigos que Atacarem alvos diferentes de você perdem d10 ESP após o Ataque ser resolvido."},"passion":{"name":"Fibra","text":"Restaure ESP ao aceitar um desafio fora de combate com as probabilidades contra você."}}},{"id":"5-4","d6":5,"d12":4,"name":{"en":"The Violet Knight","pt":"O Cavaleiro Violeta"},"en":{"property":["Grand mace (d10 long), mail (A1), reflective scale (A1)","Flattering handmirror (shows the viewer’s ideal vision of themselves)","Nameless steed (VIG 12, CLA 8, SPI 4, 1GD, see below)"],"ability":{"name":"Light Beyond Light","text":"You can cause any metal object you hold to emit a bright light that only you can see. Bees, butterflies, hummingbirds, and hedgehogs can also see the light."},"passion":{"name":"Positivity","text":"Restore SPI when you raise somebody’s mood."}},"pt":{"property":["Grande maça (d10 longa), malha (A1), brunea reflexiva (A1)","Espelho de mão lisonjeiro (mostra ao observador a visão ideal de si mesmo)","Montaria sem nome (VIG 12, CLA 8, ESP 4, 1GD, veja abaixo)"],"ability":{"name":"Luz Além da Luz","text":"Você pode fazer com que qualquer objeto de metal que esteja segurando emita uma luz brilhante que só você consegue ver. Abelhas, borboletas, beija-flores e ouriços também conseguem ver a luz."},"passion":{"name":"Positividade","text":"Restaure ESP quando elevar o ânimo de alguém."}}},{"id":"5-5","d6":5,"d12":5,"name":{"en":"The Cosmic Knight","pt":"O Cavaleiro Cósmico"},"en":{"property":["Strange crossbow (see below)","Echostone (can record and repeat one spoken phrase)","Boneless steed (VIG 10, CLA 8, SPI 5, 3GD, can squeeze through any gap as large as its head)"],"ability":{"name":"Celestial Retreat","text":"While you can see the sky you may focus for a minute to vanish to a distant sanctuary, just beyond reality. You leave a small glowing stone behind. You can rematerialise at the stone at any time."},"passion":{"name":"Constellations","text":"Restore SPI when you tell a new person about the stars as you point to them."}},"pt":{"property":["Besta estranha (veja abaixo)","Pedra-eco (pode gravar e repetir uma frase falada)","Corcel sem ossos (VIG 10, CLA 8, ESP 5, 3GD, pode se espremer por qualquer fresta do tamanho de sua cabeça)"],"ability":{"name":"Retiro Celestial","text":"Enquanto puder ver o céu, você pode se concentrar por um minuto para desaparecer rumo a um santuário distante, logo além da realidade. Você deixa uma pequena pedra brilhante para trás. Pode se rematerializar na pedra a qualquer momento."},"passion":{"name":"Constelações","text":"Restaure ESP quando falar a uma nova pessoa sobre as estrelas enquanto aponta para elas."}}},{"id":"5-6","d6":5,"d12":6,"name":{"en":"The Temple Knight","pt":"O Cavaleiro do Templo"},"en":{"property":["Spear (d8 hefty), white cloak, broadshield (d4, A1)","Mummified snake (Reptiles will not attack anyone holding it. The snake speaks to your mind directly, see below)","Moorland steed (VIG 11, CLA 9, SPI 6, 3GD, faint smell of heather)"],"ability":{"name":"Site of Respite","text":"You may declare a building that you occupy as peaceful ground. No being within the building can bring themselves to attack another until you leave."},"passion":{"name":"Quietude","text":"Restore SPI when bringing peaceful order to a chaotic place."}},"pt":{"property":["Lança (d8 pesada), manto branco, escudo largo (d4, A1)","Cobra mumificada (Répteis não atacarão ninguém que a segure. A cobra fala diretamente à sua mente; veja abaixo)","Corcel da charneca (VIG 11, CLA 9, ESP 6, 3GD, leve cheiro de urze)"],"ability":{"name":"Local de Trégua","text":"Você pode declarar uma construção que esteja ocupando como solo pacífico. Nenhum ser dentro da construção consegue atacar outro até que você saia."},"passion":{"name":"Quietude","text":"Restaure ESP ao trazer ordem pacífica a um lugar caótico."}}},{"id":"5-7","d6":5,"d12":7,"name":{"en":"The Fox Knight","pt":"O Cavaleiro da Raposa"},"en":{"property":["Jagged blade (d8 hefty), buckler (d4, A1), foxhelm (A1), hidden blade (d6, see below)","Sealing wax (can render any container watertight and airtight, restock each new Season)","Tunnel steed (VIG 10, CLA 10, SPI 5, 2GD, can see perfectly in the dark)"],"ability":{"name":"Cunning Ploy","text":"Once per day, declare your current self to be an illusion, dispersing into smoke. The real you is watching from a safe place nearby."},"passion":{"name":"Wits","text":"Restore SPI when you avoid being tricked or outwitted."}},"pt":{"property":["Lâmina denteada (d8 pesada), broquel (d4, A1), elmo-raposa (A1), lâmina oculta (d6, veja abaixo)","Cera de lacre (pode tornar qualquer recipiente estanque à água e ao ar, reabastece a cada nova Estação)","Corcel de túnel (VIG 10, CLA 10, ESP 5, 2GD, enxerga perfeitamente no escuro)"],"ability":{"name":"Estratagema Astuto","text":"Uma vez por dia, declare que o seu eu atual é uma ilusão, dispersando-se em fumaça. O seu eu verdadeiro está observando de um lugar seguro por perto."},"passion":{"name":"Astúcia","text":"Restaure ESP quando evitar ser enganado ou passado para trás."}}},{"id":"5-8","d6":5,"d12":8,"name":{"en":"The Gull Knight","pt":"O Cavaleiro da Gaivota"},"en":{"property":["Hooked blade (d8 hefty), patchwork mail (A1, see below), patterned cloak","Blinding bracelet (anybody wearing the bracelet is blind until they take it off)","Tempestuous steed (VIG 12, CLA 8, SPI 7, 4GD, dances joyfully in rain)"],"ability":{"name":"Guiding Gust","text":"Ascend to the top of a vertical surface you are touching, lifted on a burst of wind."},"passion":{"name":"Joy","text":"Restore SPI when you deliver good news."}},"pt":{"property":["Lâmina fisgada (d8 pesada), malha remendada (A1, veja abaixo), manto estampado","Bracelete cegante (qualquer um usando o bracelete fica cego até tirá-lo)","Corcel tempestuoso (VIG 12, CLA 8, ESP 7, 4GD, dança alegremente na chuva)"],"ability":{"name":"Rajada Guia","text":"Suba até o topo de uma superfície vertical que esteja tocando, erguido por uma rajada de vento."},"passion":{"name":"Alegria","text":"Restaure ESP quando entregar boas notícias."}}},{"id":"5-9","d6":5,"d12":9,"name":{"en":"The Magpie Knight","pt":"O Cavaleiro da Pega"},"en":{"property":["Heavy cudgel (d8 hefty), 3 javelins (d6)","Twofold pouch (items you place in the pouch can only be retrieved by you) containing a memento (see below)","Ironclad steed (VIG 13, CLA 5, SPI 5, 2GD, A1, d6 trample)"],"ability":{"name":"Scourer’s Sense","text":"If you are searching for something specific you always know for sure whether it is in your immediate surroundings or not."},"passion":{"name":"Heraldry","text":"Restore SPI when you announce the owner of a banner, crest, or coat of arms, which you can always recognise."}},"pt":{"property":["Porrete pesado (d8 pesado), 3 azagaias (d6)","Bolsa dupla (itens que você coloca na bolsa só podem ser retirados por você) contendo uma lembrança (veja abaixo)","Montaria encouraçada (VIG 13, CLA 5, ESP 5, 2GD, A1, d6 atropelar)"],"ability":{"name":"Sentido Vasculhador","text":"Se estiver procurando algo específico, você sempre sabe com certeza se está nos seus arredores imediatos ou não."},"passion":{"name":"Heráldica","text":"Restaure ESP quando anunciar o dono de um estandarte, timbre ou brasão de armas, os quais você sempre consegue reconhecer."}}},{"id":"5-10","d6":5,"d12":10,"name":{"en":"The Reliquary Knight","pt":"O Cavaleiro do Relicário"},"en":{"property":["War sickle (d8 hefty), gambeson (A1), carved plate (A1)","Sack of history tomes, treasured reliquary (see below)","Bearded steed (VIG 12, CLA 8, SPI 6, 3GD)"],"ability":{"name":"Spirit Call","text":"Once per day, release the invisible spirit from your reliquary. It will follow a single, specific command. It acts with the general capacities of a normal human but can be invisible and immaterial as needed."},"passion":{"name":"Tradition","text":"Restore SPI when you ensure a tradition is thoroughly honoured."}},"pt":{"property":["Foice de guerra (d8 pesada), gambeson (A1), placas entalhadas (A1)","Saco de tomos de história, relicário estimado (veja abaixo)","Corcel barbudo (VIG 12, CLA 8, ESP 6, 3GD)"],"ability":{"name":"Chamado Espiritual","text":"Uma vez por dia, liberte o espírito invisível de seu relicário. Ele seguirá um único comando específico. Age com as capacidades gerais de um humano normal, mas pode ficar invisível e imaterial conforme necessário."},"passion":{"name":"Tradição","text":"Restaure ESP quando garantir que uma tradição seja plenamente honrada."}}},{"id":"5-11","d6":5,"d12":11,"name":{"en":"The Vulture Knight","pt":"O Cavaleiro do Abutre"},"en":{"property":["Black axe (d10 long, +d10 vs wounded targets), sinister mail (A1, see below)","Spidernip nuts (acts as a pleasing stimulant for insects and arachnids when ground to a powder, restock each new Season)","Bright-eyed steed (VIG 12, CLA 9, SPI 5, 2GD)"],"ability":{"name":"Carrion Casting","text":"Spread the innards of the recently dead across the ground. Ask a single question, they point you in a direction that would help."},"passion":{"name":"Thrift","text":"Restore SPI when you make good use of something you found discarded."}},"pt":{"property":["Machado negro (d10 longo, +d10 vs alvos feridos), malha sinistra (A1, veja abaixo)","Nozes-de-aranha (atuam como um estimulante agradável para insetos e aracnídeos quando moídas até virarem pó; reabastecem a cada nova Estação)","Corcel de olhos brilhantes (VIG 12, CLA 9, ESP 5, 2GD)"],"ability":{"name":"Presságio da Carniça","text":"Espalhe as entranhas de um recém-morto pelo chão. Faça uma única pergunta; elas apontam uma direção que ajudaria."},"passion":{"name":"Parcimônia","text":"Restaure ESP quando fizer bom uso de algo que encontrou descartado."}}},{"id":"5-12","d6":5,"d12":12,"name":{"en":"The Free Knight","pt":"O Cavaleiro Livre"},"en":{"property":["Hooked flail (d8 hefty), hexshield (d4, A1, see below)","Tempest chest (when empty, it can draw a storm within, restoring calm weather. If opened when full the storm is released)","Grassy steed (VIG 11, CLA 8, SPI 5, 2GD, blends into long grass when sitting)"],"ability":{"name":"Bond Breaker","text":"Strike a chain or lock with a metal weapon. Both shatter loudly."},"passion":{"name":"Liberty","text":"Restore SPI when you release somebody from an unwanted bond."}},"pt":{"property":["Mangual fisgado (d8 pesado), escudo-hexagonal (d4, A1, veja abaixo)","Baú da tempestade (quando vazio, pode atrair uma tempestade para dentro de si, restaurando o tempo calmo. Se aberto quando cheio, a tempestade é liberada)","Corcel relvado (VIG 11, CLA 8, ESP 5, 2GD, mistura-se à grama alta quando sentado)"],"ability":{"name":"Quebra-Grilhões","text":"Golpeie uma corrente ou fechadura com uma arma de metal. Ambas se estilhaçam ruidosamente."},"passion":{"name":"Liberdade","text":"Restaure ESP quando libertar alguém de um vínculo indesejado."}}},{"id":"6-1","d6":6,"d12":1,"name":{"en":"The Silk Knight","pt":"O Cavaleiro da Seda"},"en":{"property":["Delicate halberd (d10 long), woven coat armour (A1, no protection against fire)","Intricate brass puzzle (compelling but impossible)","Young steed (VIG 9, CLA 8, SPI 6, 1GD, see below)"],"ability":{"name":"Adamant Gossamer","text":"You can draw thin strands of silky string of any length from your mouth. They are utterly unbreakable, but burn to ash in an instant."},"passion":{"name":"Mercy","text":"Restore SPI when you accept a surrender or plea for forgiveness."}},"pt":{"property":["Alabarda delicada (d10 longa), armadura de casaco tecido (A1, sem proteção contra fogo)","Quebra-cabeça intrincado de latão (fascinante, mas impossível)","Montaria jovem (VIG 9, CLA 8, ESP 6, 1GD, veja abaixo)"],"ability":{"name":"Fio Adamantino","text":"Você pode puxar fios finos e sedosos de qualquer comprimento da sua boca. São totalmente inquebráveis, mas queimam até virar cinzas em um instante."},"passion":{"name":"Misericórdia","text":"Restaure ESP quando aceitar uma rendição ou pedido de perdão."}}},{"id":"6-2","d6":6,"d12":2,"name":{"en":"The Tiger Knight","pt":"O Cavaleiro do Tigre"},"en":{"property":["Fang blades (d6, or d8 each when wielded as a pair), knotted coat (A1)","3 phoenix feathers (erupts in flame when they touch the ground, d8 blast, restock each new Season)","Tattooed steed (VIG 12, CLA 9, SPI 5, 5GD, see below)"],"ability":{"name":"Bestial Renown","text":"Each time you defeat an animal in a contest befitting its strengths, all animals of that type will react favourably to you."},"passion":{"name":"Closure","text":"Restore SPI when you get an answer that you’ve been seeking for some time."}},"pt":{"property":["Lâminas-presa (d6, ou d8 cada quando empunhadas em par), casaco atado (A1)","3 penas de fênix (irrompem em chamas quando tocam o chão, d8 explosão, reabastecem a cada nova Estação)","Montaria tatuada (VIG 12, CLA 9, ESP 5, 5GD, veja abaixo)"],"ability":{"name":"Renome Bestial","text":"Cada vez que você derrota um animal em uma disputa condizente com os pontos fortes dele, todos os animais daquele tipo reagirão favoravelmente a você."},"passion":{"name":"Desfecho","text":"Restaure ESP quando obtiver uma resposta que vem buscando há algum tempo."}}},{"id":"6-3","d6":6,"d12":3,"name":{"en":"The Leaf Knight","pt":"O Cavaleiro da Folha"},"en":{"property":["Hooked club (d8 hefty), verdant leather (A1 while within foliage), useful stick (see below)","Murmur box (creates the illusion of indistinct conversation when open)","Patchy steed (VIG 12, CLA 5, SPI 5, 3GD)"],"ability":{"name":"Nature’s Vault","text":"You can wield branches as javelins (d6) or greatspears (d10 long) and eat leaves as a satisfying meal."},"passion":{"name":"Gourmet","text":"Restore SPI when you eat a new type of fruit or vegetable."}},"pt":{"property":["Clava fisgada (d8 pesada), couro verdejante (A1 enquanto dentro da folhagem), graveto útil (veja abaixo)","Caixa de murmúrios (cria a ilusão de conversa indistinta quando aberta)","Corcel malhado (VIG 12, CLA 5, ESP 5, 3GD)"],"ability":{"name":"Cofre da Natureza","text":"Você pode empunhar galhos como azagaias (d6) ou lanças grandes (d10 longas) e comer folhas como uma refeição satisfatória."},"passion":{"name":"Gastronomia","text":"Restaure ESP quando comer um novo tipo de fruta ou vegetal."}}},{"id":"6-4","d6":6,"d12":4,"name":{"en":"The Glass Knight","pt":"O Cavaleiro de Vidro"},"en":{"property":["Two-pronged pike (d10 long), painted mail (A1, see below)","Witching needle (a six-inch spike, can be stuck into any material, and cannot be removed by anybody but you or a Seer)","Chestnut steed (VIG 11, CLA 8, SPI 6, 3GD, hated by spiders and hates them back)"],"ability":{"name":"Touch of Glass","text":"You can see through any surface that you place your hand upon."},"passion":{"name":"Curiosity","text":"Restore SPI when looking somewhere you really shouldn’t."}},"pt":{"property":["Pique de duas pontas (d10 longo), malha pintada (A1, veja abaixo)","Agulha de bruxaria (um espigão de quinze centímetros que pode ser cravado em qualquer material e não pode ser removido por ninguém além de você ou de um Vidente)","Corcel castanho (VIG 11, CLA 8, ESP 6, 3GD, odiado por aranhas e as odeia de volta)"],"ability":{"name":"Toque de Vidro","text":"Você consegue ver através de qualquer superfície sobre a qual coloque a mão."},"passion":{"name":"Curiosidade","text":"Restaure ESP ao olhar onde realmente não deveria."}}},{"id":"6-5","d6":6,"d12":5,"name":{"en":"The Hive Knight","pt":"O Cavaleiro da Colmeia"},"en":{"property":["Rootbow (d6 long), countless daggers (d6)","Tidal resin (when burned, all nearby water becomes still and solid for a while, restock each new Season)","Hooded steed (VIG 11, CLA 10, SPI 5, 3GD)"],"ability":{"name":"Chrysalent Rebirth","text":"At night you may immerse yourself in a cocoon through means you do not fully understand (see below). After a full day you emerge, your VIG restored, and any physical harm cured. This cannot cure death unless the process requires it."},"passion":{"name":"Community","text":"Restore SPI when you leave a community better off than when you arrived."}},"pt":{"property":["Arco de raiz (d6 longo), incontáveis adagas (d6)","Resina das marés (quando queimada, toda a água próxima fica imóvel e sólida por um tempo; reabastece a cada nova Estação)","Corcel encapuzado (VIG 11, CLA 10, ESP 5, 3GD)"],"ability":{"name":"Renascimento Crisálida","text":"À noite você pode imergir em um casulo por meios que não compreende totalmente (veja abaixo). Após um dia inteiro você emerge, com seu VIG restaurado e qualquer dano físico curado. Isso não pode curar a morte, a menos que o processo o exija."},"passion":{"name":"Comunidade","text":"Restaure ESP quando deixar uma comunidade em situação melhor do que quando chegou."}}},{"id":"6-6","d6":6,"d12":6,"name":{"en":"The Ghoul Knight","pt":"O Cavaleiro Carniçal"},"en":{"property":["Bearded axe (d10 long), dusty mail (A1)","Cleaner salt (renders even the most rotten food safe and delicious, restock each new Season), animal miniature (see below)","Faithful steed (VIG 12, CLA 8, SPI 5, 3GD, will never abandon you)"],"ability":{"name":"Rebuked by Death","text":"Use when you are dead. Return to life. Your body is as you left it, as are your Guard and Virtue scores."},"passion":{"name":"Acceptance","text":"Restore SPI when warmly welcomed into somebody’s home."}},"pt":{"property":["Machado barbudo (d10 longo), malha empoeirada (A1)","Sal purificador (torna até a comida mais podre segura e deliciosa; reabastece a cada nova Estação), miniatura de animal (veja abaixo)","Corcel fiel (VIG 12, CLA 8, ESP 5, 3GD, nunca o abandonará)"],"ability":{"name":"Rejeitado pela Morte","text":"Use quando estiver morto. Retorne à vida. Seu corpo está como você o deixou, assim como seus valores de Guarda e Virtudes."},"passion":{"name":"Aceitação","text":"Restaure ESP ao ser calorosamente recebido no lar de alguém."}}},{"id":"6-7","d6":6,"d12":7,"name":{"en":"The Weaver Knight","pt":"O Cavaleiro Tecelão"},"en":{"property":["Two-headed axe (d8 hefty), bronze buckler (d4, A1), thrown weapon (d6, see below)","Hushcloth (items fully wrapped in this cloth create no noise)","Orchard steed (VIG 12, CLA 9, SPI 5, 1GD, can sniff out fruit)"],"ability":{"name":"Warp & Weft","text":"Swap the positions of an object you are holding and another object you can see. They must be of a similar size and shape, such as two swords."},"passion":{"name":"Detachment","text":"Restore SPI when you discard something that you want."}},"pt":{"property":["Machado de duas cabeças (d8 pesado), broquel de bronze (d4, A1), arma de arremesso (d6, veja abaixo)","Pano-silêncio (itens totalmente envoltos neste pano não produzem ruído)","Corcel do pomar (VIG 12, CLA 9, ESP 5, 1GD, consegue farejar frutas)"],"ability":{"name":"Urdidura & Trama","text":"Troque as posições de um objeto que você esteja segurando e de outro objeto que possa ver. Eles devem ter tamanho e forma semelhantes, como duas espadas."},"passion":{"name":"Desapego","text":"Restaure ESP quando descartar algo que você deseja."}}},{"id":"6-8","d6":6,"d12":8,"name":{"en":"The Thunder Knight","pt":"O Cavaleiro do Trovão"},"en":{"property":["Forked spear (d8 hefty), oakshield (d4, A1)","Caged bug (VIG 2, CLA 6, SPI 3, 5GD, see below)","Overfed steed (VIG 12, CLA 6, SPI 5, 2GD, d6 trample)"],"ability":{"name":"Voice of the Skies","text":"While outdoors, you can shout loud enough to be heard clearly throughout the whole Hex and all adjacent Hexes."},"passion":{"name":"Discord","text":"Restore SPI when you disrupt a place of order."}},"pt":{"property":["Lança bifurcada (d8 pesada), escudo de carvalho (d4, A1)","Inseto engaiolado (VIG 2, CLA 6, ESP 3, 5GD, veja abaixo)","Montaria superalimentada (VIG 12, CLA 6, ESP 5, 2GD, d6 atropelar)"],"ability":{"name":"Voz dos Céus","text":"Enquanto estiver ao ar livre, você pode gritar alto o suficiente para ser ouvido claramente por todo o Hexágono e todos os Hexágonos adjacentes."},"passion":{"name":"Discórdia","text":"Restaure ESP quando perturbar um lugar de ordem."}}},{"id":"6-9","d6":6,"d12":9,"name":{"en":"The Dust Knight","pt":"O Cavaleiro da Poeira"},"en":{"property":["Old hammer (d8), inscribed shield (d4, A1)","Beckoning net (fish wilfully swim into this fishing net), preserved fish (see below, restock each new Season)","Spotted steed (VIG 12, CLA 9, SPI 5, 3GD, hated by other horses)"],"ability":{"name":"Aqueous Repulsion","text":"You can forcefully repel liquids with an outstretched hand, enough to hold a river at bay for a while."},"passion":{"name":"Entitlement","text":"Restore SPI when you get something that you were denied."}},"pt":{"property":["Martelo velho (d8), escudo inscrito (d4, A1)","Rede convidativa (os peixes nadam voluntariamente para dentro desta rede de pesca), peixe em conserva (veja abaixo, reabastece a cada nova Estação)","Corcel malhado (VIG 12, CLA 9, ESP 5, 3GD, odiado por outros cavalos)"],"ability":{"name":"Repulsão Aquosa","text":"Você pode repelir líquidos com força usando a mão estendida, o bastante para conter um rio por algum tempo."},"passion":{"name":"Privilégio","text":"Restaure ESP quando conseguir algo que lhe foi negado."}}},{"id":"6-10","d6":6,"d12":10,"name":{"en":"The Fanged Knight","pt":"O Cavaleiro Presa"},"en":{"property":["Forked blade (d8 hefty), chain mail (A1), shell plates (A1)","Ancient scroll (has references to places in this Realm, but outdated, see below)","Noble steed (VIG 12, CLA 5, SPI 7, 4GD)"],"ability":{"name":"Sink Teeth","text":"You can bite (d6) someone, choosing one of the following effects before the bite, occurring only if you Wound them: • Regain VIG equal to the VIG that they lose • Lower them into normal sleep • Show them one of your memories"},"passion":{"name":"Melancholy","text":"Restore SPI when you dampen the mood."}},"pt":{"property":["Lâmina bifurcada (d8 pesada), cota de malha (A1), placas de concha (A1)","Pergaminho ancestral (contém referências a lugares neste Reino, mas desatualizadas; veja abaixo)","Corcel nobre (VIG 12, CLA 5, ESP 7, 4GD)"],"ability":{"name":"Cravar as Presas","text":"Você pode morder (d6) alguém, escolhendo um dos seguintes efeitos antes da mordida, ocorrendo apenas se você o Ferir: • Recupere VIG igual ao VIG que ele perder • Levá-los a um sono normal • Mostrar a eles uma de suas memórias"},"passion":{"name":"Melancolia","text":"Restaure ESP quando esfriar o ânimo do ambiente."}}},{"id":"6-11","d6":6,"d12":11,"name":{"en":"The Pearl Knight","pt":"O Cavaleiro da Pérola"},"en":{"property":["Seablade (2d8 long, see below), glossy mail (A1), demi-plate (A1)","Salincense (smoke from this candle causes plants to wither and die in seconds)","Rose steed (VIG 12, CLA 9, SPI 5, 3GD)"],"ability":{"name":"Gift from the Deep","text":"Produce one pearl each morning, unless you haven’t given or traded your previous pearl. You can see through the eyes of anybody that is carrying one of your pearls."},"passion":{"name":"Gossip","text":"Restore SPI when you share or receive gossip."}},"pt":{"property":["Lâmina-marinha (2d8 longa, veja abaixo), malha lustrosa (A1), meia-placa (A1)","Incenso-de-sal (a fumaça desta vela faz as plantas murcharem e morrerem em segundos)","Corcel rosado (VIG 12, CLA 9, ESP 5, 3GD)"],"ability":{"name":"Dádiva das Profundezas","text":"Produza uma pérola a cada manhã, a menos que não tenha dado ou trocado sua pérola anterior. Você pode ver através dos olhos de qualquer pessoa que esteja carregando uma de suas pérolas."},"passion":{"name":"Fofoca","text":"Restaure ESP quando compartilhar ou receber fofocas."}}},{"id":"6-12","d6":6,"d12":12,"name":{"en":"The Rat Knight","pt":"O Cavaleiro do Rato"},"en":{"property":["Pole sickle (d10 long), 3 darts (d6), modified gambeson (A1, see below)","Listening horn (when placed against a wall, hear everything from the other side in perfect clarity)","Matted steed (VIG 12, CLA 8, SPI 5, 3GD)"],"ability":{"name":"Verminform","text":"Take the form of a rat to squeeze into any space that a rat could fit into. You return to your normal form as soon as you are in a space that allows it. You can also speak with rats, who are generally helpful."},"passion":{"name":"Trust","text":"Restore SPI when giving the benefit of the doubt in a way that leaves you vulnerable."}},"pt":{"property":["Foice de haste (d10 longa), 3 dardos (d6), gambeson modificado (A1, veja abaixo)","Corneta de escuta (quando colocada contra uma parede, ouve tudo do outro lado com perfeita clareza)","Corcel emaranhado (VIG 12, CLA 8, ESP 5, 3GD)"],"ability":{"name":"Forma de Verme","text":"Assuma a forma de um rato para se espremer em qualquer espaço onde um rato caberia. Você retorna à sua forma normal assim que estiver em um espaço que permita isso. Você também pode falar com ratos, que são geralmente prestativos."},"passion":{"name":"Confiança","text":"Restaure ESP ao dar o benefício da dúvida de modo que o deixe vulnerável."}}}];
